1	import { useCallback, useEffect, useState } from "react";
2	import { Button } from "@/presentation/components/ui/button";
3	import {
4		type DeckSlide as DeckSlideData,
5		LESSON_ASSET_ROOT,
6		type LessonDeck,
7		renderRuleSlide,
8		validateDeck,
9	} from "../../../domain/script/data/lessonContent";
10	import { useResetOnCardChange } from "../../hooks/useResetOnCardChange";
11	
12	interface Props {
13		/** Path of the deck's JSON, served from `public/lessons/<id>/deck.json`. */
14		deckPath: string;
15		/** Fires once, when the deck's own last slide is confirmed forward. */
16		onComplete: () => void;
17	}
18	
19	type LoadState =
20		| { readonly status: "loading" }
21		| { readonly status: "error"; readonly message: string }
22		| {
23				readonly status: "ready";
24				readonly deck: LessonDeck;
25				readonly audioUrls: ReadonlyMap<string, string>;
26		  };
27	
28	/**
29	 * Every asset path a deck names for playback must resolve inside its own
30	 * `public/lessons/<lessonId>/` — the trust boundary the deck-JSON sink is
31	 * named against. A URL outside that root, or one containing `..`, is
32	 * dropped rather than played.
33	 */
34	function extractAudioUrls(
35		raw: unknown,
36		lessonId: string,
37	): ReadonlyMap<string, string> {
38		const map = new Map<string, string>();
39		if (typeof raw !== "object" || raw === null) return map;
40		const slidesRaw = (raw as Record<string, unknown>).slides;
41		if (!Array.isArray(slidesRaw)) return map;
42	
43		const prefix = `${LESSON_ASSET_ROOT}/${lessonId}/`;
44		for (const item of slidesRaw) {
45			if (typeof item !== "object" || item === null) continue;
46			const id = (item as Record<string, unknown>).id;
47			const audioUrl = (item as Record<string, unknown>).audioUrl;
48			if (
49				typeof id === "string" &&
50				typeof audioUrl === "string" &&
51				audioUrl.startsWith(prefix) &&
52				!audioUrl.includes("..")
53			) {
54				map.set(id, audioUrl);
55			}
56		}
57		return map;
58	}
59	
60	/**
61	 * True only for a deck that is structurally sound and simply has no slides
62	 * yet: `slides` is an empty array and the retrieval invariant
63	 * (`missing-retrieval`) is the *only* reported error — meaning `lessonId` and
64	 * `title` already passed validation. Any other error, or any actual slide,
65	 * routes to the ordinary failure state instead.
66	 */
67	function isUnauthoredEmptyDeck(
68		raw: unknown,
69		errors: readonly { readonly code: string }[],
70	): boolean {
71		if (typeof raw !== "object" || raw === null) return false;
72		const slides = (raw as Record<string, unknown>).slides;
73		if (!Array.isArray(slides) || slides.length > 0) return false;
74		return errors.length === 1 && errors[0]?.code === "missing-retrieval";
75	}
76	
77	function ReplayButton({ url }: { url: string }) {
78		return (
79			<button
80				type="button"
81				onClick={() => {
82					new Audio(url).play().catch(() => {});
83				}}
84				className="inline-flex items-center justify-center w-12 h-12 rounded-full text-2xl transition-colors"
85				style={{
86					background: "var(--color-surface-2)",
87					color: "var(--color-primary)",
88				}}
89				aria-label="Replay audio"
90			>
91				🔊
92			</button>
93		);
94	}
95	
96	/** Renders the one currently-visible slide of an already-loaded deck. */
97	function DeckSlideContent({
98		deck,
99		slide,
100		audioUrl,
101	}: {
102		deck: LessonDeck;
103		slide: DeckSlideData;
104		audioUrl?: string;
105	}) {
106		// Reveal state for a "reveal" slide, mirroring `Flashcard.tsx`'s own
107		// click-to-reveal pattern — the established mechanism in this repo, not a
108		// second one. Reset (and re-triggered playback below) keys on the slide's
109		// own identity so two consecutive slides that happen to share one audio
110		// clip still reset — see AC5.
111		const [revealed, setRevealed] = useState(false);
112		useResetOnCardChange(slide.id, () => {
113			setRevealed(false);
114		});
115	
116		// biome-ignore lint/correctness/useExhaustiveDependencies: keys on the slide's own identity, not on audioUrl — two consecutive slides sharing a clip must still reset (see AC5)
117		useEffect(() => {
118			if (audioUrl && slide.kind !== "reveal") {
119				new Audio(audioUrl).play().catch(() => {});
120			}
121		}, [slide.id]);
122	
123		// A "reveal" slide's audio is the answer's pronunciation, so it plays on
124		// reveal rather than on arrival — hearing it first would answer the
125		// retrieval step it follows. Mirrors `Flashcard.tsx`'s own reveal-time
126		// audio effect.
127		// biome-ignore lint/correctness/useExhaustiveDependencies: fires once per reveal, not on every audioUrl/slide identity change
128		useEffect(() => {
129			if (revealed && audioUrl) {
130				new Audio(audioUrl).play().catch(() => {});
131			}
132		}, [revealed]);
133	
134		switch (slide.kind) {
135			case "exposition":
136				return (
137					<div className="space-y-4">
138						<h2 className="text-lg font-bold text-center">{slide.heading}</h2>
139						<div className="space-y-2">
140							{slide.body.map((paragraph, i) => (
141								// biome-ignore lint/suspicious/noArrayIndexKey: body is a static ordered list of paragraphs with no other identity
142								<p key={i} className="text-center">
143									{paragraph}
144								</p>
145							))}
146						</div>
147						{audioUrl && (
148							<div className="flex justify-center">
149								<ReplayButton url={audioUrl} />
150							</div>
151						)}
152					</div>
153				);
154			case "retrieval":
155				// The answer lives on the reveal slide this one names, never here — the
156				// schema itself refuses a retrieval slide that carries one.
157				return (
158					<div className="space-y-4">
159						<p className="text-center text-lg">{slide.prompt}</p>
160						{audioUrl && (
161							<div className="flex justify-center">
162								<ReplayButton url={audioUrl} />
163							</div>
164						)}
165					</div>
166				);
167			case "reveal":
168				return (
169					<div className="space-y-4">
170						{!revealed ? (
171							<button
172								type="button"
173								onClick={() => setRevealed(true)}
174								className="w-full py-4 rounded-xl text-lg font-semibold transition-colors"
175								style={{
176									background: "var(--color-surface-2)",
